solutionCode:
function findMax(nums) {
  let max = nums[0];
  for (let i = 1; i < nums.length; i++) {
    if (nums[i] > max) max = nums[i];
  }
  return max;
}
module.exports = { findMax };

testHarness:
const { findMax } = require('./solution.js');

const cases = [
  { label: '[3, 1, 5, 2, 4]', input: [3, 1, 5, 2, 4], expected: 5 },
  { label: '[10]', input: [10], expected: 10 },
  { label: '[-3, -1, -5, -2]', input: [-3, -1, -5, -2], expected: -1 },
  { label: '[-100, -50, -1, -200]', input: [-100, -50, -1, -200], expected: -1 },
];

for (const c of cases) {
  try {
    const actual = findMax(c.input);
    if (actual === c.expected) {
      console.log(`PASS\t${c.label}`);
    } else {
      console.log(`FAIL\t${c.label}\t${c.expected}\t${actual}`);
    }
  } catch (e) {
    console.log(`ERROR\t${c.label}\t${e.name}: ${e.message}`);
  }
}
